from save_review import save
from pathlib import Path
import json
C={a['number']:a for a in json.loads((Path(__file__).parents[2]/'全书分段底稿.json').read_text())}
def replacements(n,pairs):
 d={}
 for b in C[n]['blocks']:
  if b['language']=='en' or b['kind']=='image':continue
  v=b['text']
  for old,new in pairs:v=v.replace(old,new)
  if v!=b['text']:d[int(b['id'][-4:])]=v
 return d
d=replacements(1534,[('空投舱','空降舱'),('空投仓','空降舱')]);d.update({
2:'空降舱主要由星际战士和混沌星际战士使用，是进行轨道突入的单程运输工具。',
7:'阿斯塔特自大远征时代起便使用空降舱。它的外观与工作方式类似舰船救生舱，可运送12名普通星际战士、一台无畏机甲，或一门雷火炮。打击巡洋舰或战斗驳船在低轨道上将其射向战场内或附近的着陆区。空降舱穿越大气层急速下坠，再由反推喷口减速；机魂负责导航，也可接收母舰进一步指令。着陆后，它不能自行移动，但战团科技战士可以回收并再次使用。回收通常由不适合进入交战区的大型运输舰艇完成，再送回原投放舰，必要时维修，供下一场战斗使用。因此，许多空降舱已经服役数百年。有些战团会把历次空降记录刻在内舱壁上，让后来的战斗兄弟阅读，从中获得迎战的勇气。',
20:'渡鸦突击舱——用途类似跳帮鱼雷，用来攻击虚空中的其他舰船或空间站。战将级泰坦也可使用一种改型，将部队送上敌方城墙。',24:'死亡风暴空降舱——也称死风空降舱，不搭载部队，而是装有旋风发射器或突击炮。着陆展开后，它会以猛烈火力扫射敌人，可以直接投向敌阵中心，为随后的进攻作准备。',28:'卡律布狄斯突击爪——大远征和荷鲁斯之乱期间，阿斯塔特军团使用的巨型空降舱兼运输艇。',32:'无畏机甲空降舱——用于尽快将一台无畏机甲投入战场。',34:'Dreadnought Drop Pod 无畏机甲空降舱',
38:'运载上升舱——荷鲁斯之乱期间，从星际战士军团控制的卫星或小型天体上向敌舰发射。其引擎能够克服较弱的引力，升入太空后又能按需迅速变向。前端装甲罩可以在撞击目标时保护舱内的军团战士。',40:'军团帕利塞德空降舱——搭载强大的护盾发生器，投射能量力场，保护其他空降舱及其搭载的部队和物资。',
47:'艾弗森神庙刺客使用特制空降舱部署。舱内神经接口会向刺客传输任务详情，远程连接则唤醒并调节他的身体，使其做好执行任务的准备。',
49:'战斗修女在执行特殊高风险任务时，偶尔会使用多米尼卡型空降舱，可搭载5名未经强化的人类。任务包括敌后渗透、精确打击高价值目标，以及瘫痪叛变星际战士战团的指挥体系。这类行动通常由异端审判庭提出请求，帝国海军提供支援。各战斗修会都保留少量专用空降舱，仅供洁天使、御天使等精锐使用。她们也使用死风空降舱的改型，武器换成修女偏好的五组双联重型爆矢枪，或多管热熔。',
51:'Mission of Sisters of Battle and their Rhinos landing via a drop pod 一支战斗修女分队及其犀牛装甲车通过空降舱着陆',53:'部分国教舰船，例如雷神之锤号，还装有能容纳数辆载具及随行步兵的巨型空降舱，可直接由宏炮发射。舱体外部设有许多探照灯，着陆后用来照亮周围。',56:'类型：载员轨道空降舱',64:'乘员：无',76:'实用升限：不适用',78:'最高下降速度：12,000公里/小时',80:'航程：无限制（原文如此）'})
save(1534,d,title='空降舱 Drop Pod',notes={49:'原译将Ordo Hereticus误作攘外修会，已按用户选定的异端审判庭修正；Dominion依官方Dominion Squad御天使小队统一词根。',44:'本段描述现时代仅混沌使用恐怖爪；不据此否认大远征/荷鲁斯之乱中的早期使用。',80:'参数表写Unlimited，照译并保留原文；不推定其能源无限。'},terms=[('Corvus Assault Pod','渡鸦突击舱'),('Deathstorm Drop Pod','死亡风暴空降舱'),('Deathwind Drop Pod','死风空降舱'),('Dreadnought Drop Pod','无畏机甲空降舱'),('Support Drop Pod','支援空降舱'),('Carrier Ascent Pod','运载上升舱'),('Legion Palisade Drop Pod','军团帕利塞德空降舱'),('Dominica-pattern Drop Pod','多米尼卡型空降舱'),('Hammer of Thor','雷神之锤号')])
save(1535,{2:'卡律布狄斯突击爪是大远征和荷鲁斯之乱期间阿斯塔特军团使用的一种空降舱。',7:'卡律布狄斯体型庞大，能搭载大批突击部队穿越虚空，并以强大火力击穿敌方小型飞行器的拦截。它也是功能完整的登陆艇，能够往返轨道与地面；舱内部队出击之前，可以先用风暴发射器和热熔切割器扫清着陆区。',9:'一些进取好战的指挥官还将它用于猎杀坦克，以低空突击直接撞击敌方装甲载具。',14:'卡律布狄斯与恐怖爪源自同一套机械技术。后来，其机械核心发展出某种智能，对特定主人产生依恋。主人一旦离开或阵亡，机器便可能做出难以预测的举动，例如在穿越大气层下降时打开舱门，让舱内人员被烧死。',16:'大清洗期间，忠诚派星际战士停止使用卡律布狄斯，但叛徒军团仍保留这种载具。核心中愤恨的机魂逐渐变成具有黑暗意识与恶意的存在，与叛徒军团愈发相称。'},notes={14:'machine-lore是机械知识/技术，不是同一个机魂；Legiones Astartes是阿斯塔特军团，不是阿斯塔特老兵。'})
save(1536,{2:'星际战士登陆艇是大型轨道突击载具，用于迅速把载具和部队送到行星表面。按本条目的描述，离开母舰后仅二三十秒，部队与载具便能着地投入战斗。',6:'登陆艇配有多挺风暴爆矢枪、双联重型爆矢枪和一对炮塔激光炮等武器，并装有大型液压夹具，以类似雷鹰运输机的方式运载星际战士坦克。'},notes={2:'二三十秒为英文原文的设定说法，未依现实轨道飞行时间自行改数。'},terms=[('Space Marine Landing Craft','星际战士登陆艇')])
save(1537,{2:'斯佩图姆突击撞击艇（原稿名“间隙突击艇”）是人类帝国使用的多种突击撞击艇之一。大远征期间，星际战士军团曾使用它。'},title='斯佩图姆突击撞击艇 Spaetum Assault Ram',notes={2:'Spaetum是型号专名，所给英文没有“间隙”词义依据；暂音译斯佩图姆，官方名称待核。'},terms=[('Spaetum Assault Ram','斯佩图姆突击撞击艇')])
d=replacements(1538,[('拳套突击艇','拳套突击撞击艇')]);d.update({
2:'拳套突击撞击艇是人类帝国多种突击撞击艇之一，也是星际战士战团最常用的型号。它比雷鹰和跳帮鱼雷小，用于太空中的近距离跳帮作战。紧凑的艇体有厚重装甲保护，设计目的就是直接撞入敌方舰船，将突击部队送入其中。',7:'自大远征以来，拳套便作为舰对舰跳帮艇在帝国服役。经历荷鲁斯之乱和此后的无数战争，到了第41个千年，它仍是星际战士的现役装备。',
10:'与其他跳帮方式相比，拳套凭借加厚装甲、短时助推火箭和加力发动机，拥有惊人的速度与坚固程度，但航程和用途较为有限。乘员在有防爆护盾的驾驶舱中操纵它；主武器为巨型热熔，另有两具翼装炽怒导弹发射器。双联重装甲艇首共能搭载一支10人的全副武装星际战士小队。前部还装有几乎独有的惯性与后坐力补偿系统，称为“仁慈”系统（misericorde，亦作Misericordia）。多组可伸缩惯性抑制夹具与动力盔甲或终结者盔甲相连，将战士固定；只要冲击尚不足以摧毁整艘艇，它就能保护乘员。',
12:'拳套原本只用于跳帮。阿坎·兰德重新发现的技术，使它能够加装反重力板，参与地面行动。常见升级包括传送信标和破片突击发射器。',
15:'执行撞击突击时，拳套先用巨型热熔削弱敌舰装甲，再以装甲艇首撞穿舰体，让乘员经前方突击坡道登舰。安装反重力线圈之后，它也可参与轨道空降并提供地面支援，作为重型战斗悬浮载具，以大型热熔武器摧毁敌方坦克和地堡。不过，多数战团仍将这些任务交给雷鹰和空降舱，将拳套留作太空战或最危险的着陆区突击之用。舰基战团尤其常用它攻击小行星基地和太空废船。',
17:'即使拳套在行动中受损，星际战士也会尽力将这件神圣器械从战场回收，哪怕它深陷敌舰或堡垒内部。',20:'类型：突击撞击艇',40:'实用升限：不适用',44:'航程：大气层内22,000公里',48:'次要武器：两具炽怒导弹发射器',62:'血腥匕首号——太空野狼所属',64:'绯红追击者号——红色猎手所属',66:'死亡怨灵号——星辰幻影所属'})
save(1538,d,title='拳套突击撞击艇 Caestus Assault Ram',notes={10:'原译把保护范围译反：short of one which could destroy the entire craft表示无法保证承受足以毁掉全艇的撞击。“仁慈”是艇载系统，不能套为禁军同名的怜悯之刃。',15:'英文前文Magna-Melta、本段Mega-Melta用词不一致；按同一艇载武器统一巨型热熔并保留英文异写。'},terms=[('Misericordia (Caestus system)','仁慈系统'),('Misericorde (Caestus system)','仁慈系统'),('Firefury Missile Launcher','炽怒导弹发射器'),('Amaranth Fang','不朽獠牙号'),('Gore Dagger','血腥匕首号'),('Secutor Crimson','绯红追击者号'),('Spectre of Death','死亡怨灵号')])
save(1539,{
2:'风暴鸟是星际战士军团在大远征期间使用的突击运输机，有些型号甚至早于大远征；后来才出现体型较小的雷鹰。',
7:'风暴鸟原本用于取代统一战争时期较老的天空长枪炮艇，既能在虚空中航行，也能在大气层内飞行。统一战争末期，因德尼赛克集团首先在泰拉制造它，用来对付泛太平洋部落。它至少可搭载50名全副武装的星际战士；也可改运最多5台无畏机甲，包括强大的利维坦，或搭载跳跃步兵、细剑炮组、摩托、喷气摩托、一辆犀牛装甲运输车，以及混合编组。标准武装为四组炮塔双联激光炮、三组双联重型爆矢枪和六枚恐惧打击导弹。它采用高密度复合装甲，并有多台虚空盾发生器提供保护；护盾还能向外延伸，掩护下机的部队和战争机器。除防御激光炮之外，地面火力都难以穿透其护盾。',
9:'风暴鸟贯穿整个大远征时期。到了荷鲁斯之乱，多数军团已经改用更小、更灵活的雷鹰；影月苍狼却有意将风暴鸟留在现役，因为它自军团初创时便载着战士奔赴沙场。驾驶舱内，两名星际战士背靠背而坐，另有两名以固定接口连接的机仆辅助。叛乱时期，前死亡守卫连长纳撒尼尔·伽罗遵照掌印者马卡多的命令，乘风暴鸟前往各个星球。与伽罗的盔甲一样，这架飞机没有军团徽记和涂色，通体为灰色。',
13:'第41个千年末期，风暴鸟几乎只存在于传说中。近千年来已无新机制造，因为让这种庞然大物运作的许多技术早已失传。不过，怀言者、钢铁勇士等混沌星际战士仍在使用一些古老的风暴鸟。',
16:'索卡型是风暴鸟的专用登陆艇改型，帝国陆军称其为“死亡鸟”。它由战鹰和内普罗斯级突击艇发展而来，因德尼赛克集团在统一战争中使用，后来帝国也予以采用。它是帝国较大型的飞行器之一，也是雷鹰的直接前身。',21:'西克里型——混沌领主塔古斯·达拉维克曾在军团战争中使用。',25:'火鸟号——福格瑞姆的专用运输机。',29:'福金号——黎曼·鲁斯的专用运输机。',31:'鲜血打击号——休伦·黑心的专用运输机。'},
notes={24:'Other Known Patterns标题下混列型号及具名运输机；保留原结构，不将所有名字都视为批量生产型号。'},terms=[('Stormbird Dropship','风暴鸟空降艇'),('Sokar Pattern Stormbird','索卡型风暴鸟'),('Nephoros Class Assault Craft','内普罗斯级突击艇'),('Apophis pattern Stormbird','阿波菲斯型风暴鸟'),('Sykri pattern Stormbird','西克里型风暴鸟'),('Warhawk VI','战鹰 VI 型'),('Heilmark','海尔马克'),('Bloodstrike (Stormbird)','鲜血打击号（风暴鸟）'),('Dreadstrike Missile','恐惧打击导弹')])
save(1540,{2:'鹰翼是阿斯塔特军团在荷鲁斯之乱时期使用的一种突击运输机。',4:'泰拉也曾使用鹰翼的民用型号。'},terms=[('Hawkwing','鹰翼'),('Hawkwing Assault Transport Aircraft','鹰翼突击运输机')])
save(1541,{2:'奥格斯飞行器是大远征期间阿斯塔特军团使用的一种帝国反重力载具。',6:'标准武器包括激光炮和导弹发射器。'},terms=[('Orgus Flyer','奥格斯飞行器')])
save(1542,{7:'剑尾的起源早已失传，但设计与霹雳、安哈特航行者等飞行器所用的标准模板构造有相似之处。806.M30，帝国从拉达曼迪斯飞地引进了这一型号。它的飞行性能会给驾驶员身体带来极大负担，而星际战士天生具备承受这种负荷的能力。',9:'剑尾可在大气层及太空中作战，配有两对双联激光炮和一具剑尾旋转导弹发射器。强大火力加上出色的速度与灵活性，使它成为致命对手。但其结构复杂、航程有限，机械教也更青睐体型较大的愤怒战斗机。因此，大远征末期，除黑暗天使与极限战士外，各军团都已将它撤出一线；荷鲁斯之乱的战时需求，又迫使许多军团重新启用它。',11:'剑尾性能很高，但发动机需要兼顾真空及多种大气环境，阿斯塔特驾驶员必须不断细调，才能保持飞机平衡。此外，机体过于轻巧，动力也不足，经常让驾驶员苦恼。不过，他们仍十分欣赏它迅捷的转弯、灵活性和对操纵输入的敏锐响应。',15:'虽然诞生于大远征时代，剑尾仍是当代星际战士战团军械库的重要部分。可适配多种任务的武装，使它能有效打击空中与地面目标。它由经验丰富的战斗兄弟驾驶。'},notes={2:'首段称最早于荷鲁斯之乱使用，正文则明确806.M30引进、大远征结束前退出现役；保留英文自身的时间矛盾。'},terms=[('Xiphon Pattern Interceptor','剑尾型截击机'),('Amhut Voyager','安哈特航行者'),('Rhadamanthys Enclave','拉达曼迪斯飞地'),('Wrath fighter','愤怒战斗机'),('Xiphon Rotary Missile Launcher','剑尾旋转导弹发射器')])
d=replacements(1543,[('风暴隼截击机','风暴鹰拦截者战机'),('风暴隼','风暴鹰')]);d.update({2:'风暴鹰拦截者战机是星际战士使用的战斗机兼炮艇。',7:'它与风暴爪同源，专门用于夺取制空权。厚重的正面装甲与强大火力让它擅长近距空战，能穿越云层，接连击落目标。机群释放的干扰弹在空中形成金色光环，诱偏来袭火力，也向敌人宣告：这片天空属于帝皇。它还能在虚空中充当攻击机，由母舰的磁力挂架释放。',9:'机体覆盖厚重陶钢，用来抵御重返大气层时的高温。驾驶舱也采用装甲防护，舍弃透明座舱盖，改由前置镜头组向飞行员传输图像。它还配有复杂的防御干扰系统，迷惑敌方武器。',13:'其武装包括双联突击炮、伊卡洛斯风暴炮或激光爪，以及双联重型爆矢枪、台风导弹发射器或天锤导弹发射器等，另有炼狱光环发射器。武器由目标瞄准系统引导。'})
save(1543,d,title='风暴鹰拦截者战机 Stormhawk Interceptor',notes={9:'foregoing a clear canopy意为舍弃透明座舱盖，原译意思相反。'},terms=[('Infernum Halo Launcher','炼狱光环发射器'),('Kyrolius','基洛留斯')])
save(1544,{2:'死亡鸟截击机是大远征和荷鲁斯之乱期间阿斯塔特军团使用的一类战斗机，外形据称像鹰。'},terms=[('Deathbird Interceptor','死亡鸟截击机')])
